static class Trie {
    Trie[] sub;
    boolean end = false;
    public Trie() {
        sub = new Trie[26];
    }
    public void insert(String word) {
        Trie it = this;
        for (char c : word.toCharArray()) {
            if (it.sub[c - 'a'] == null) {
                it.sub[c - 'a'] = new Trie();
            }
            it = it.sub[c - 'a'];
        }
        it.end = true;
    }
    public boolean search(String word) {
        Trie it = this;
        for (char c : word.toCharArray()) {
            if (it.sub[c - 'a'] == null) {
                return false;
            }
            it = it.sub[c - 'a'];
        }
        return it.end;
    }
    public boolean startsWith(String prefix) {
        Trie it = this;
        for (char c : prefix.toCharArray()) {
            if (it.sub[c - 'a'] == null) {
                return false;
            }
            it = it.sub[c - 'a'];
        }
        return it != null;
    }
}

